package agentusageview

import (
	"errors"
	"io/fs"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"testing"
	"time"

	"github.com/anthnel/devdesk/internal/agentusage"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// Live updates, step 2 (DEVDESK-45): the messages and Cmds of the poll chain.

// copyFixture copies the basic fixture into t.TempDir() and returns its parent
// transcript, so a test can append to it and delete it.
func copyFixture(t *testing.T) string {
	t.Helper()
	src := filepath.Join(filepath.Dir(fixtureParent), "..", "..")
	dst := t.TempDir()
	err := filepath.WalkDir(src, func(p string, d fs.DirEntry, err error) error {
		if err != nil {
			return err
		}
		rel, _ := filepath.Rel(src, p)
		target := filepath.Join(dst, rel)
		if d.IsDir() {
			return os.MkdirAll(target, 0o700)
		}
		b, err := os.ReadFile(p)
		if err != nil {
			return err
		}
		return os.WriteFile(target, b, 0o600)
	})
	if err != nil {
		t.Fatal(err)
	}
	rel, _ := filepath.Rel(src, fixtureParent)
	return filepath.Join(dst, rel)
}

// runDelta runs readDeltaCmd and returns its answer.
func runDelta(t *testing.T, gen int, c agentusage.Cursor) usageDeltaMsg {
	t.Helper()
	cmd := readDeltaCmd(gen, c)
	if cmd == nil {
		t.Fatal("readDeltaCmd returned nil")
	}
	got, ok := cmd().(usageDeltaMsg)
	if !ok {
		t.Fatalf("readDeltaCmd answered %T, want usageDeltaMsg", cmd())
	}
	return got
}

func withSessions(t *testing.T, parents ...string) Model {
	t.Helper()
	var ss []agentusage.Session
	for i, p := range parents {
		s := session("id-"+string(rune('a'+i))+"000000-0000", "/srv/p"+string(rune('a'+i)), time.Duration(i)*time.Hour)
		s.Parent = p
		ss = append(ss, s)
	}
	return loaded(t, newModel(t), ss...)
}

// opened presses → on the selected row and returns the model and the Cmd.
func opened(t *testing.T, m Model, key string) (Model, tea.Cmd) {
	t.Helper()
	updated, cmd := m.Update(testutil.Key(key))
	next, ok := updated.(Model)
	if !ok {
		t.Fatalf("Update returned %T", updated)
	}
	return next, cmd
}

// answer shows u as the answer to the read in flight: it goes through the same
// entry the delta handler uses once the aggregate has applied the delta
// (withUsage), then marks the read as answered. Synthetic usage cannot travel
// as a Delta, whose fields are private to internal/agentusage.
func answer(t *testing.T, m Model, u agentusage.Usage) Model {
	t.Helper()
	m = m.withUsage(u, true)
	m.reading = false
	return m
}

// batchMsgs runs every Cmd of a batch concurrently and returns what they
// produced. testutil.Msgs would do the same; this one is bounded so a stuck
// Cmd fails the test instead of hanging it.
func batchMsgs(t *testing.T, cmd tea.Cmd) []tea.Msg {
	t.Helper()
	if cmd == nil {
		return nil
	}
	cmds := []tea.Cmd{cmd}
	if b, ok := cmd().(tea.BatchMsg); ok {
		cmds = b
	}
	out := make(chan tea.Msg, len(cmds))
	for _, c := range cmds {
		go func() {
			if c == nil {
				out <- nil
				return
			}
			out <- c()
		}()
	}
	var msgs []tea.Msg
	for range cmds {
		select {
		case m := <-out:
			msgs = append(msgs, m)
		case <-time.After(5 * time.Second):
			t.Fatal("a Cmd of the batch did not answer")
		}
	}
	return msgs
}

func usageMsgs(msgs []tea.Msg) []usageDeltaMsg {
	var got []usageDeltaMsg
	for _, m := range msgs {
		if u, ok := m.(usageDeltaMsg); ok {
			got = append(got, u)
		}
	}
	return got
}

// ── Opening ──────────────────────────────────────────────────────────────────
	}
}

// ── Errors ───────────────────────────────────────────────────────────────────

func TestAReadErrorKeepsTheRowsAndStartsNothing(t *testing.T) {
	m, _ := atFixture(t)
	m.reading = true
	updated, next := m.Update(usageDeltaMsg{gen: m.agentGen, err: errors.New("boom")})
	m = updated.(Model)
	if next != nil {
		t.Error("an error answer starts nothing before the poll chain exists")
	}
	if !m.agentsErr || m.agentsLoading || m.reading {
		t.Errorf("agentsErr=%v agentsLoading=%v reading=%v, want true, false, false", m.agentsErr, m.agentsLoading, m.reading)
	}
	if !strings.Contains(m.View(), "├─ coder") {
		t.Error("rows already shown stay after a failure")
	}
	if !strings.Contains(footer(m), "Failed to read this session") {
		t.Errorf("footer should report the failure:\n%s", footer(m))
	}
}

func TestOnlyTheFirstFailureOfAStreakIsLogged(t *testing.T) {
	buf := captureLog(t)
	m, _ := atFixture(t)
	fail := func() {
		m.reading = true
		m = feed(t, m, usageDeltaMsg{gen: m.agentGen, err: errors.New("boom")})
	}
	succeed := func() {
		m.reading = true
		m = feed(t, m, runDelta(t, m.agentGen, m.agg.Cursor()))
	}

	fail()
	fail()
	if n := strings.Count(buf.String(), logTag); n != 1 {
		t.Fatalf("two failures in a row: %d log lines, want 1", n)
	}
	succeed()
	if m.agentsErr {
		t.Error("a successful read ends the failure state")
	}
	fail()
	if n := strings.Count(buf.String(), logTag); n != 2 {
		t.Errorf("a failure after a success is a new streak: %d log lines, want 2", n)
	}
}

