func TestASuccessEndsTheSeriesSoTheNextFailureIsLoggedAgain(t *testing.T) {
	buf := captureLog(t)
	m, _ := atFixture(t)
	step := func(msg usageDeltaMsg) {
		var msgs []tea.Msg
		m, msgs = pollTick(t, m, m.agentGen)
